-- Issue 08: historical zero placeholder and atomic custom-rate bundle.
begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('d0310800-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','issue08-'||n||'@example.test','',now(),'{"provider":"email","providers":["email"]}','{"display_name":"Issue 08"}',now(),now() from generate_series(1,4) n;
create temp table i8(k text primary key, v uuid);
insert into i8 select 'u'||n, p.id from generate_series(1,4) n join public.participants p on p.auth_user_id=('d0310800-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
create function pg_temp.id(key text) returns uuid language sql as $$ select v from i8 where k=$1 $$;
create function pg_temp.claim(n int) returns void language plpgsql as $$ begin perform set_config('request.jwt.claims', jsonb_build_object('sub','d0310800-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','is_anonymous',false)::text, true); end $$;
create function pg_temp.payload(ids uuid[], paid bigint[], shares bigint[], amount bigint, currency text) returns jsonb language sql as $$ select jsonb_build_object('expense_scope','space','target_space_id',pg_temp.id('trip'),'participant_ids',ids,'contribution_amounts',paid,'share_amounts',shares,'total_minor',amount,'currency_code',currency,'description','Issue 08','category','Food','occurred_on','2026-11-03') $$;
grant all on table i8 to authenticated;
set local role authenticated;
select pg_temp.claim(1);
insert into i8 values('trip', public.create_space('trip','Issue 08 Trip',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role) values (pg_temp.id('trip'),pg_temp.id('u2'),'full_access'),(pg_temp.id('trip'),pg_temp.id('u3'),'view'),(pg_temp.id('trip'),pg_temp.id('u4'),'view');
set local role authenticated;
select pg_temp.claim(2);
insert into i8 values('bill', (public.create_trip_expense_editor(gen_random_uuid(), pg_temp.id('trip'), pg_temp.payload(array[pg_temp.id('u2'),pg_temp.id('u3')], array[17200,0], array[8600,8600], 17200, 'MYR'), array[pg_temp.id('u2'),pg_temp.id('u3')])->>'expense_id')::uuid);
select pg_temp.claim(1);
select lives_ok($$select public.remove_space_member(pg_temp.id('trip'), pg_temp.id('u3'))$$, 'owner can remove a member without rewriting bills');
select pg_temp.claim(2);
select lives_ok($$select public.save_trip_expense_editor(gen_random_uuid(), pg_temp.id('bill'), 1, pg_temp.id('trip'), 'shared', false, pg_temp.payload(array[pg_temp.id('u2'),pg_temp.id('u3')], array[17200,0], array[17200,0], 17200, 'MYR'), array[pg_temp.id('u2')])$$, 'removed member can remain as a zero placeholder');
select throws_ok($$select public.save_trip_expense_editor(gen_random_uuid(), (select id from public.expenses where corrects_expense_id=pg_temp.id('bill')), 1, pg_temp.id('trip'), 'shared', false, pg_temp.payload(array[pg_temp.id('u2'),pg_temp.id('u3')], array[17200,0], array[8600,8600], 17200, 'MYR'), array[pg_temp.id('u2'),pg_temp.id('u3')])$$, 'P0001', 'participant_not_in_space', 'a removed member cannot receive a new positive share');
insert into i8 values('myr', (public.create_trip_expense_editor(gen_random_uuid(), pg_temp.id('trip'), pg_temp.payload(array[pg_temp.id('u2'),pg_temp.id('u4')], array[10000,0], array[0,10000], 10000, 'MYR'), array[pg_temp.id('u2'),pg_temp.id('u4')])->>'expense_id')::uuid);
insert into i8 values('vnd', (public.create_trip_expense_editor(gen_random_uuid(), pg_temp.id('trip'), pg_temp.payload(array[pg_temp.id('u4'),pg_temp.id('u2')], array[120000,0], array[0,120000], 120000, 'VND'), array[pg_temp.id('u4'),pg_temp.id('u2')])->>'expense_id')::uuid);
insert into i8 values('account', (public.create_personal_account(gen_random_uuid(),'Issue 08 cash','cash','MYR',null,null,false)->>'account_id')::uuid);
select pg_temp.claim(4);
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 4000, pg_temp.id('account'))$$, 'P0001', 'settlement_cash_account_invalid', 'a debtor cannot pay from someone else''s account');
insert into i8 values('account4', (public.create_personal_account(gen_random_uuid(),'Issue 08 payer','cash','MYR',null,null,false)->>'account_id')::uuid);
insert into i8 values('request', gen_random_uuid());
insert into i8 values('bundle', (public.propose_fx_settlement_bundle(pg_temp.id('request'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 4000, pg_temp.id('account4'))->>'bundle_id')::uuid);
select is((public.propose_fx_settlement_bundle(pg_temp.id('request'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 4000, pg_temp.id('account4'))->>'bundle_id')::uuid, pg_temp.id('bundle'), 'the same request does not create a second bundle');
select is((select status from public.settlement_fx_bundles where id=pg_temp.id('bundle')), 'pending', 'a proposal does not settle before confirmation');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 10000::bigint, 'pending bundle does not reduce the original balance');
set local role authenticated;
select pg_temp.claim(1);
select throws_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('bundle'), 'accepted', 1)$$, 'P0001', 'settlement_participant_denied', 'a third member cannot confirm the bundle');
select pg_temp.claim(2);
insert into i8 values('account2', (public.create_personal_account(gen_random_uuid(),'Issue 08 receiver','cash','MYR',null,null,false)->>'account_id')::uuid);
select throws_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('bundle'), 'accepted', 1, pg_temp.id('account4'))$$, 'P0001', 'settlement_cash_account_invalid', 'the receiver cannot be paid into the payer account');
select lives_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('bundle'), 'accepted', 1, pg_temp.id('account2'))$$, 'the counterparty accepts the whole bundle');
select is((select status from public.settlement_fx_bundles where id=pg_temp.id('bundle')), 'accepted', 'acceptance is atomic');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 5000::bigint, 'half of the MYR obligation remains');
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u2'), pg_temp.id('u4'), 'VND'), 60000::bigint, 'half of the VND offset remains');
select is((select count(*) from public.settlement_payments where fx_cash_only and note='fx-cash'), 1::bigint, 'one cash fact is recorded and is excluded from the debt balance above');
select is((select coalesce(sum(entry.amount_minor),0)::bigint from public.personal_account_entries entry join public.personal_account_transactions tx on tx.id=entry.transaction_id where tx.owner_participant_id=pg_temp.id('u4') and tx.kind='settlement_out'), -4000::bigint, 'the payer cash account is reduced once');
select is((select coalesce(sum(entry.amount_minor),0)::bigint from public.personal_account_entries entry join public.personal_account_transactions tx on tx.id=entry.transaction_id where tx.owner_participant_id=pg_temp.id('u2') and tx.kind='settlement_in'), 4000::bigint, 'the receiver cash account is increased once');
select is((select count(*) from public.personal_account_transactions where kind in ('income','expense_funding')), 0::bigint, 'cash settlement is not income or spending');
select pg_temp.claim(4);
select throws_ok($$select public.reverse_settlement_allocation(gen_random_uuid(), (select a.id from public.settlement_allocations a join public.settlement_payments p on p.id=a.settlement_payment_id where p.note='fx-coverage' limit 1), 1, 'split')$$, 'P0001', 'fx_bundle_reversal_required', 'one coverage cannot be reversed alone');
select pg_temp.claim(4);
insert into i8 values('again', gen_random_uuid());
insert into i8 values('second', (public.propose_fx_settlement_bundle(pg_temp.id('again'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 2000, pg_temp.id('account4'))->>'bundle_id')::uuid);
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 4000, pg_temp.id('account4'))$$, 'P0001', 'invalid_amount', 'a second request cannot cover the amount already reserved');
select pg_temp.claim(2);
select lives_ok($$select public.respond_fx_settlement_bundle(pg_temp.id('second'), 'declined', 1, null)$$, 'the receiver can decline');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 5000::bigint, 'declining does not change the remaining debt');
select is((select count(*) from public.personal_account_transactions where kind='settlement_out'), 1::bigint, 'declining does not post another cash entry');
set local role authenticated;
select pg_temp.claim(4);
insert into i8 values('later', gen_random_uuid());
insert into i8 values('third', (public.propose_fx_settlement_bundle(pg_temp.id('later'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"6000"}'::jsonb, 1000, pg_temp.id('account4'))->>'bundle_id')::uuid);
select lives_ok($$select public.cancel_fx_settlement_bundle(pg_temp.id('third'), 1)$$, 'the payer can cancel a pending bundle');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 5000::bigint, 'cancelling releases the reservation without adding debt');
set local role authenticated;
select pg_temp.claim(2);
select lives_ok($$select public.reverse_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('bundle'), 2)$$, 'either party can reverse the whole bundle');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u4'), pg_temp.id('u2'), 'MYR'), 10000::bigint, 'reversal restores the MYR debt');
select is(private.space_signed_outstanding(pg_temp.id('trip'), pg_temp.id('u2'), pg_temp.id('u4'), 'VND'), 120000::bigint, 'reversal restores the VND debt');
select is((select coalesce(sum(entry.amount_minor),0)::bigint from public.personal_account_entries entry join public.personal_account_transactions tx on tx.id=entry.transaction_id where tx.owner_participant_id=pg_temp.id('u4') and tx.kind in ('settlement_out','reversal')), 0::bigint, 'payer cash nets back to zero');
select is((select coalesce(sum(entry.amount_minor),0)::bigint from public.personal_account_entries entry join public.personal_account_transactions tx on tx.id=entry.transaction_id where tx.owner_participant_id=pg_temp.id('u2') and tx.kind in ('settlement_in','reversal')), 0::bigint, 'receiver cash nets back to zero');
reset role;
insert into tabby_fx.snapshots(id,rates,fetched_at) values ('d0310800-0000-4000-8000-000000000099', '{"VND":{"currency":"VND","quote":"MYR","numerator":"1","denominator":"6000","provider":"Frankfurter","rateDate":"2026-11-03"}}'::jsonb, now());
update tabby_fx.refresh_state set snapshot_id='d0310800-0000-4000-8000-000000000099', failure=null, succeeded_at=now();
set local role authenticated;
select pg_temp.claim(4);
insert into i8 values('system-request', gen_random_uuid());
select lives_ok($$select public.propose_fx_settlement_bundle(pg_temp.id('system-request'), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'system', '{}'::jsonb, 4000, pg_temp.id('account4'))$$, 'a system snapshot can price the same net');
select is((select quote->'rates'->'VND'->>'provider' from public.settlement_fx_bundles where client_request_id=pg_temp.id('system-request')), 'Frankfurter', 'the system quote keeps the provider');
select is((select quote->'rates'->'VND'->>'rateDate' from public.settlement_fx_bundles where client_request_id=pg_temp.id('system-request')), '2026-11-03', 'the system quote keeps the rate date');
reset role;
update tabby_fx.snapshots set rates='{}'::jsonb where id='d0310800-0000-4000-8000-000000000099';
set local role authenticated;
select pg_temp.claim(4);
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('trip'), pg_temp.id('u2'), 'MYR', 'system', '{}'::jsonb, 4000, pg_temp.id('account4'))$$, 'P0001', 'fx_rate_unavailable', 'a missing system rate is rejected');
reset role;
update public.expenses set version=version+1 where id=pg_temp.id('myr');
set local role authenticated;
select pg_temp.claim(4);
select throws_ok($$select public.respond_fx_settlement_bundle((select id from public.settlement_fx_bundles where client_request_id=pg_temp.id('system-request')), 'accepted', 1, pg_temp.id('account2'))$$, 'P0001', 'settlement_participant_denied', 'the payer cannot confirm');
select pg_temp.claim(2);
select throws_ok($$select public.respond_fx_settlement_bundle((select id from public.settlement_fx_bundles where client_request_id=pg_temp.id('system-request')), 'accepted', 1, pg_temp.id('account2'))$$, 'P0001', 'balance_changed', 'a changed source expense blocks confirmation');
reset role;
select is((select count(*) from public.personal_account_transactions where kind='settlement_out'), 1::bigint, 'a rejected confirmation does not post cash');
set local role authenticated;
select pg_temp.claim(1);
insert into i8 values('tiny', public.create_space('trip','Issue 08 Tiny',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role) values (pg_temp.id('tiny'),pg_temp.id('u2'),'full_access'),(pg_temp.id('tiny'),pg_temp.id('u4'),'view');
set local role authenticated;
select pg_temp.claim(2);
insert into i8 values('tiny-bill', (public.create_trip_expense_editor(gen_random_uuid(), pg_temp.id('tiny'), jsonb_build_object('expense_scope','space','target_space_id',pg_temp.id('tiny'),'participant_ids',array[pg_temp.id('u2'),pg_temp.id('u4')],'contribution_amounts',array[1,0],'share_amounts',array[0,1],'total_minor',1,'currency_code','VND','description','Tiny','category','Food','occurred_on','2026-11-03'), array[pg_temp.id('u2'),pg_temp.id('u4')])->>'expense_id')::uuid);
select pg_temp.claim(4);
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(), pg_temp.id('tiny'), pg_temp.id('u2'), 'MYR', 'custom', '{"VND":"0.01"}'::jsonb, 1, pg_temp.id('account4'))$$, 'P0001', 'amount_too_small', 'a partial that covers no source minor is rejected');
select * from finish();
rollback;
